mapper.select:
select b.*, i.title as itemTitle, i.price as itemPrice, i.seller_id as sellerId,
       u.nickname as buyerNickname
from bargain b
left join item i on b.item_id = i.id
left join `user` u on b.buyer_id = u.id


        and b.buyer_id = #{userId}
        and i.seller_id = #{userId}

    and b.status = #{status}

order by b.created_at desc

select count(*)
from bargain b
left join item i on b.item_id = i.id

    where b.buyer_id = #{userId}
    where i.seller_id = #{userId}

and b.status = 'PENDING'
